import java.util.*;

public class Main {
    double myPow(double x, int n) {
        long exponent = n;
        if (exponent < 0) {
            x = 1 / x;                    // a negative exponent means take the reciprocal instead
            exponent = -exponent;
        }
        double result = 1;
        for (long i = 0; i < exponent; i++) {
            result *= x;                    // multiply in one more copy of x, one at a time
        }
        return result;
    }

    public static void main(String[] args) {
        double x = 2.0;
        int n = 10;
        Main solution = new Main();
        System.out.println(solution.myPow(x, n));
    }
}

