def my_pow(x, n):
    if n < 0:
        x = 1 / x                 # a negative exponent means take the reciprocal instead
        n = -n
    result = 1
    current_product = x            # holds x, then x squared, then x to the 4th, doubling each round
    while n > 0:
        if n % 2 == 1:
            result *= current_product  # this bit of n is set, fold in the current power of x
        current_product *= current_product  # move to the next power of two
        n //= 2
    return result


if __name__ == "__main__":
    x, n = 2.0, 10
    print(my_pow(x, n))

